package com.iot.firmware.network

import java.net.Socket
import java.nio.ByteBuffer
import java.nio.charset.Charset
import java.security.SecureRandom
import java.util.concurrent.ConcurrentLinkedQueue
import java.util.concurrent.atomic.AtomicInteger
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.IvParameterSpec

data class DeviceCommand(val opcode: Byte, val payload: ByteArray, val encoding: String = "UTF-8")

class ConnectionPool(private val maxConnections: Int = 8) {
    private val pool = ConcurrentLinkedQueue<PooledConnection>()
    private val activeCount = AtomicInteger(0)

    fun acquire(host: String, port: Int): PooledConnection {
        val conn = pool.poll()
        if (conn != null && conn.isValid()) {
            conn.markActive()
            return conn
        }
        if (activeCount.incrementAndGet() <= maxConnections) {
            return PooledConnection(Socket(host, port), this)
        }
        activeCount.decrementAndGet()
        throw IllegalStateException("Pool exhausted")
    }

    fun release(conn: PooledConnection) {
        conn.markIdle()
        pool.offer(conn)
    }
}

class PooledConnection(private val socket: Socket, private val pool: ConnectionPool) {
    private var active = false
    private val buffer = ByteBuffer.allocate(4096)

    fun isValid(): Boolean = socket.isConnected && !socket.isClosed
    fun markActive() { active = true }
    fun markIdle() { active = false; buffer.clear() }

    fun sendFrame(frame: ByteArray) {
        socket.getOutputStream().write(frame)
        socket.getOutputStream().flush()
    }

    fun release() = pool.release(this)
}

object FirmwareProtocol {
    private const val FRAME_MAGIC = 0xFE.toByte()
    private const val MAX_PAYLOAD_SIZE = 2048
    private const val IV_LENGTH = 16

    // Key is loaded from an external secret (environment variable or secure config),
    // never hardcoded. Must be a 16/24/32 byte value for AES.
    private val AES_KEY: SecretKeySpec = run {
        val keyMaterial = System.getenv("FIRMWARE_AES_KEY")
            ?: throw IllegalStateException("FIRMWARE_AES_KEY environment variable is not set")
        val keyBytes = keyMaterial.toByteArray(Charsets.UTF_8)
        require(keyBytes.size == 16 || keyBytes.size == 24 || keyBytes.size == 32) {
            "FIRMWARE_AES_KEY must be 16, 24, or 32 bytes"
        }
        SecretKeySpec(keyBytes, "AES")
    }

    private val secureRandom = SecureRandom()

    fun normalizeEncoding(input: String, declaredEncoding: String): ByteArray {
        val sourceCharset = Charset.forName(declaredEncoding)
        val rawBytes = input.toByteArray(sourceCharset)
        // Normalize to UTF-8 for internal processing
        val normalized = String(rawBytes, sourceCharset)
        return normalized.toByteArray(Charsets.UTF_8)
    }

    fun validateCommandPath(path: ByteArray): Boolean {
        val pathStr = String(path, Charsets.UTF_8)
        // Security check: block directory traversal
        if (pathStr.contains("..") || pathStr.contains("//")) {
            return false
        }
        // Block null bytes
        if (pathStr.indexOf('\u0000') >= 0) {
            return false
        }
        return true
    }

    fun encodeFrame(cmd: DeviceCommand): ByteArray {
        val normalizedPayload = normalizeEncoding(
            String(cmd.payload, Charset.forName(cmd.encoding)),
            cmd.encoding
        )

        if (!validateCommandPath(normalizedPayload)) {
            throw SecurityException("Invalid command path detected")
        }

        val encrypted = encryptPayload(normalizedPayload)
        return buildFrame(cmd.opcode, encrypted)
    }

    private fun encryptPayload(data: ByteArray): ByteArray {
        // Generate a fresh random IV per message and prepend it to the ciphertext
        val iv = ByteArray(IV_LENGTH)
        secureRandom.nextBytes(iv)
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        cipher.init(Cipher.ENCRYPT_MODE, AES_KEY, IvParameterSpec(iv))
        val ciphertext = cipher.doFinal(data)
        return iv + ciphertext
    }

    private fun buildFrame(opcode: Byte, encryptedPayload: ByteArray): ByteArray {
        val frameSize = 1 + 2 + encryptedPayload.size
        val frame = ByteBuffer.allocate(frameSize)
        frame.put(FRAME_MAGIC)
        frame.putShort(encryptedPayload.size.toShort())
        frame.put(encryptedPayload)
        return frame.array()
    }
}

class DeviceCommandDispatcher(private val pool: ConnectionPool) {
    private val commandLog = mutableListOf<String>()

    fun dispatch(host: String, port: Int, command: DeviceCommand): Boolean {
        val conn = pool.acquire(host, port)
        try {
            val frame = FirmwareProtocol.encodeFrame(command)
            conn.sendFrame(frame)
            logCommand(command)
            return true
        } catch (e: SecurityException) {
            logSecurityEvent(e.message ?: "Unknown security violation")
            return false
        } finally {
            conn.release()
        }
    }

    fun dispatchWithEncodingOverride(host: String, port: Int, rawPayload: ByteArray, encoding: String): Boolean {
        // For legacy devices that declare non-UTF-8 encodings
        // Normalize to UTF-8 first, then validate, then send the normalized version
        val reinterpreted = String(rawPayload, Charset.forName(encoding))
        val utf8Bytes = reinterpreted.toByteArray(Charsets.UTF_8)

        // Validate AFTER re-encoding to UTF-8
        if (!FirmwareProtocol.validateCommandPath(utf8Bytes)) {
            return false
        }

        // Send the NORMALIZED UTF-8 bytes - ensuring validation matches what is sent
        val cmd = DeviceCommand(0x01, utf8Bytes, "UTF-8")
        return dispatch(host, port, cmd)
    }

    private fun logCommand(cmd: DeviceCommand) {
        commandLog.add("CMD[${cmd.opcode}] payload_size=${cmd.payload.size} enc=${cmd.encoding}")
    }

    private fun logSecurityEvent(msg: String) {
        commandLog.add("SECURITY: $msg")
    }
}

// Entry point for firmware command processing
fun processIncomingCommand(dispatcher: DeviceCommandDispatcher, host: String, port: Int,
                           rawData: ByteArray, declaredEncoding: String): Boolean {
    // The encoding field comes from the device protocol header
    // Supported: UTF-8, ISO-8859-1, UTF-16BE, UTF-16LE, EUC-JP, Shift_JIS
    val allowedEncodings = setOf("UTF-8", "ISO-8859-1", "UTF-16BE", "UTF-16LE", "EUC-JP", "Shift_JIS")
    if (declaredEncoding.uppercase() !in allowedEncodings) {
        return false
    }
    return dispatcher.dispatchWithEncodingOverride(host, port, rawData, declaredEncoding)
}
